const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var countries = ee.FeatureCollection("FAO/GAUL/2015/level0");
  var vietnam = countries.filter(ee.Filter.eq('ADM0_NAME', 'Viet Nam'));
  var myanmar = countries.filter(ee.Filter.eq('ADM0_NAME', 'Myanmar'));

  // Check if geometries exist
  var vietnamGeom = vietnam.geometry();
  var myanmarGeom = myanmar.geometry();

  var date = '2018-02-03';
  var nextDay = '2018-02-04';  // exclusive end date

  // Helper function to get fire count for a geometry
  function getFireCount(geometry, collectionName, scale) {
    var col = ee.ImageCollection(collectionName)
                .filterDate(date, nextDay)
                .filterBounds(geometry);
    var count = col.size();
    // If collection empty, return null
    if (count.getInfo() === 0) {
      return null;
    }
    // Combine images (if multiple) by taking max confidence or count pixels
    // We'll count all fire pixels across the day
    var fireImg = col.select('T21').max(); // Using T21 band (brightness temperature)
    // Count pixels where T21 > 0 (indicating fire detection)
    var fireMask = fireImg.gt(0);
    var pixelCount = fireMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('T21');
    return pixelCount;
  }

  // Try VIIRS first (higher resolution)
  var scaleVIIRS = 375;
  var vietnamCount = getFireCount(vietnamGeom, 'NOAA/VIIRS/001/VNP14IMGDL', scaleVIIRS);
  var myanmarCount = getFireCount(myanmarGeom, 'NOAA/VIIRS/001/VNP14IMGDL', scaleVIIRS);

  // If VIIRS fails (null), try MODIS
  if (vietnamCount === null || myanmarCount === null) {
    var scaleMODIS = 1000;
    vietnamCount = getFireCount(vietnamGeom, 'MODIS/006/MCD14DL', scaleMODIS);
    myanmarCount = getFireCount(myanmarGeom, 'MODIS/006/MCD14DL', scaleMODIS);
  }

  // Check for no data
  if (vietnamCount === null || myanmarCount === null) {
    print("No fire data for one or both countries on " + date);
    print("<answer>C1</answer>");
    return;
  }

  // Get pixel counts
  var vCount = vietnamCount.getInfo();
  var mCount = myanmarCount.getInfo();

  // Check for no valid pixels
  if (vCount === 0 && mCount === 0) {
    print("Vietnam fires: 0, Myanmar fires: 0");
    print("<answer>B</answer>");
    return;
  }

  // Validate counts (not NaN)
  if (isNaN(vCount) || isNaN(mCount)) {
    print("Calculation failed (NaN)");
    print("<answer>C3</answer>");
    return;
  }

  // Print results
  print("Vietnam fire detections: " + vCount);
  print("Myanmar fire detections: " + mCount);

  // Compare
  if (vCount > mCount) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
